const ids = ["task", "submission", "source"];
const rs = await Promise.all(ids.map(evidence_id => tools.mcp__mrhbench__evidence_read({evidence_id, start_char:0, max_chars:6000})));
for (let i=0;i<rs.length;i++) {
  text(`EVIDENCE ${ids[i]}`);
  for (const c of (rs[i].content || [])) {
    if (c.type === "image") image(c, "original");
    else if (c.type === "text") text(c.text);
    else text(JSON.stringify(c));
  }
}

